\n  filter: saturate(0.8) contrast(1.06) brightness(0.52);\\n  transform: scale(1.03);\\n}\\n\\n.studio-room-shell {\\n  position: relative;\\n  isolation: isolate;\\n}\\n\\n.studio-room-shell::before {\\n  content: '';\\n  position: fixed;\\n  inset: 0;\\n  pointer-events: none;\\n  background:\\n    radial-gradient(900px 420px at 50% -6%, rgba(214, 169, 92, 0.08), transparent 70%),\\n    radial-gradient(840px 420px at 88% 8%, rgba(122, 214, 209, 0.08), transparent 72%);\\n  z-index: -3;\\n  animation: ambient-shift 36s ease-in-out infinite alternate;\\n}\\n\\n.studio-room-shell::after {\\n  content: '';\\n  position: fixed;\\n  inset: 0;\\n  pointer-events: none;\\n  background:\\n    radial-gradient(circle at center, transparent 56%, rgba(0, 0, 0, 0.46) 100%),\\n    repeating-linear-gradient(0deg, rgba(255,255,255,0.008), rgba(255,255,255,0.008) 1px, transparent 2px, transparent 4px);\\n  mix-blend-mode: soft-light;\\n  opacity: 0.45;\\n  z-index: -2;\\n}\\n\\n.shell-overview::before {\\n  background:\\n    radial-gradient(700px 360px at 24% 8%, rgba(122, 214, 209, 0.12), transparent 72%),\\n    radial-gradient(840px 420px at 76% 12%, rgba(214, 169, 92, 0.1), transparent 74%);\\n}\\n\\n.shell-writers::before {\\n  background:\\n    radial-gradient(700px 380px at 18% 10%, rgba(214, 169, 92, 0.12), transparent 72%),\\n    radial-gradient(820px 420px at 76% 16%, rgba(159, 141, 197, 0.09), transparent 74%);\\n}\\n\\n.shell-previs::before {\\n  background:\\n    radial-gradient(720px 400px at 14% 10%, rgba(122, 214, 209, 0.12), transparent 72%),\\n    repeating-linear-gradient(90deg, rgba(255,255,255,0.018), rgba(255,255,255,0.018) 3px, transparent 5px, transparent 20px);\\n}\\n\\n.shell-production::before {\\n  background:\\n    radial-gradient(720px 400px at 80% 10%, rgba(184, 135, 98, 0.12), transparent 72%),\\n    linear-gradient(120deg, rgba(255,255,255,0.02), transparent 45%);\\n}\\n\\n.shell-screening::before {\\n  background:\\n    radial-gradient(860px 420px at 50% -4%, rgba(122, 214, 209, 0.1), transparent 70%),\\n    linear-gradient(180deg, rgba(0,0,0,0.12), transparent 30%);\\n}\\n\\n.shell-archive::before {\\n  background:\\n    radial-gradient(700px 380px at 20% 8%, rgba(159, 141, 197, 0.1), transparent 72%),\\n    radial-gradient(760px 360px at 80% 14%, rgba(214, 169, 92, 0.1), transparent 72%);\\n}\\n\\n.shell-study::before {\\n  background:\\n    radial-gradient(760px 400px at 18% 8%, rgba(122, 214, 209, 0.1), transparent 72%),\\n    radial-gradient(760px 420px at 82% 16%, rgba(214, 169, 92, 0.08), transparent 74%);\\n}\\n\\n.cinematic-panel {\\n  transition: opacity 220ms ease, transform 220ms ease, border-color 220ms ease, box-shadow 220ms ease;\\n  animation: panel-fade-in 220ms ease both;\\n}\\n\\n.cinematic-panel:hover {\\n  transform: translateY(-2px);\\n  border-color: rgba(214, 169, 92, 0.35);\\n  box-shadow: 0 18px 38px rgba(0, 0, 0, 0.42), 0 0 0 1px rgba(214, 169, 92, 0.08) inset;\\n}\\n\\n.room-hero-frame {\\n  position: relative;\\n  overflow: hidden;\\n}\\n\\n.room-hero-frame::after {\\n  content: '';\\n  position: absolute;\\n  inset: -1px;\\n  pointer-events: none;\\n  border: 1px solid rgba(122, 214, 209, 0.34);\\n  box-shadow: 0 0 26px rgba(122, 214, 209, 0.14);\\n  border-radius: inherit;\\n}\\n\\n.tab-active-glow {\\n  position: relative;\\n}\\n\\n.tab-active-glow::after {\\n  content: '';\\n  position: absolute;\\n  left: 10%;\\n  right: 10%;\\n  bottom: -2px;\\n  height: 1px;\\n  background: linear-gradient(90deg, transparent, rgba(214, 169, 92, 0.92), transparent);\\n  animation: tab-slide 180ms ease both;\\n}\\n\\n.status-pulse-soft {\\n  animation: status-pulse 2.6s ease-in-out infinite;\\n}\\n\\n.playback-glow {\\n  animation: playback-pulse 1.8s ease-in-out infinite;\\n}\\n\\n.dropzone-glow {\\n  box-shadow: 0 0 0 1px rgba(214, 169, 92, 0.45), 0 0 26px rgba(214, 169, 92, 0.2);\\n}\\n\\n.skeleton-shimmer {\\n  position: relative;\\n  overflow: hidden;\\n  background: rgba(255, 255, 255, 0.06);\\n}\\n\\n.skeleton-shimmer::after {\\n  content: '';\\n  position: absolute;\\n  inset: 0;\\n  transform: translateX(-100%);\\n  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.12), transparent);\\n  animation: shimmer 1.6s ease-in-out infinite;\\n}\\n\\n@keyframes ambient-shift {\\n  from { transform: translate3d(-1%, 0, 0) scale(1); }\\n  to { transform: translate3d(1%, 0.5%, 0) scale(1.03); }\\n}\\n\\n@keyframes panel-fade-in {\\n  from { opacity: 0; transform: translateY(5px); }\\n  to { opacity: 1; transform: translateY(0); }\\n}\\n\\n@keyframes tab-slide {\\n  from { opacity: 0; transform: scaleX(0.4); }\\n  to { opacity: 1; transform: scaleX(1); }\\n}\\n\\n@keyframes shimmer {\\n  100% { transform: translateX(100%); }\\n}\\n\\n@keyframes status-pulse {\\n  0%, 100% { box-shadow: 0 0 0 rgba(245, 158, 11, 0); }\\n  50% { box-shadow: 0 0 16px rgba(245, 158, 11, 0.26); }\\n}\\n\\n@keyframes playback-pulse {\\n  0%, 100% { box-shadow: 0 0 0 rgba(122, 214, 209, 0.12); }\\n  50% { box-shadow: 0 0 22px rgba(122, 214, 209, 0.32); }\\n}\\n\\n@media (prefers-reduced-motion: reduce) {\\n  .studio-room-shell::before,\\n  .cinematic-panel,\\n  .status-pulse-soft,\\n  .playback-glow,\\n  .skeleton-shimmer::after,\\n  .tab-active-glow::after {\\n    animation: none !important;\\n    transition: none !important;\\n  }\\n}\\n\\n.studio-landing-grain {\\n  position: absolute;\\n  inset: 0;\\n  pointer-events: none;\\n  opacity: 0.16;\\n  background-image: radial-gradient(rgba(255, 255, 255, 0.25) 0.4px, transparent 0.4px);\\n  background-size: 3px 3px;\\n  mix-blend-mode: soft-light;\\n}\\n\\n.studio-landing-vignette {\\n  position: absolute;\\n  inset: 0;\\n  pointer-events: none;\\n  background:\\n    radial-gradient(120% 120% at 50% 50%, transparent 44%, rgba(0, 0, 0, 0.72) 100%),\\n    linear-gradient(180deg, rgba(2, 4, 7, 0.16), rgba(2, 4, 7, 0.44));\\n}\\n\\n.studio-landing-content {\\n  position: relative;\\n  z-index: 2;\\n  text-align: center;\\n  padding: 1.5rem;\\n}\\n\\n.studio-landing-title {\\n  margin: 0;\\n  font-size: clamp(3rem, 9vw, 7rem);\\n  font-weight: 700;\\n  letter-spacing: 0.26em;\\n  color: var(--color-text-primary);\\n  text-shadow: 0 0 20px rgba(0, 0, 0, 0.42), 0 0 45px rgba(0, 212, 170, 0.15);\\n}\\n\\n.studio-landing-subtitle {\\n  margin: 0.85rem 0 2.2rem;\\n  font-size: clamp(0.9rem, 2vw, 1.18rem);\\n  letter-spacing: 0.2em;\\n  text-transform: uppercase;\\n  color: var(--color-text-secondary);\\n}\\n\\n.studio-landing-enter {\\n  border: 1px solid rgba(0, 212, 170, 0.5);\\n  border-radius: 999px;\\n  background: linear-gradient(135deg, rgba(0, 212, 170, 0.15), rgba(0, 212, 170, 0.05));\\n  color: var(--color-text-primary);\\n  font-size: 0.76rem;\\n  font-weight: 700;\\n  text-transform: uppercase;\\n  letter-spacing: 0.18em;\\n  padding: 0.82rem 1.8rem;\\n  cursor: pointer;\\n  transition: transform 220ms ease, box-shadow 220ms ease, background 220ms ease;\\n}\\n\\n.studio-landing-enter:hover {\\n  transform: translateY(-1px) scale(1.02);\\n  box-shadow: 0 0 26px rgba(0, 212, 170, 0.3);\\n  background: linear-gradient(135deg, rgba(0, 212, 170, 0.2), rgba(0, 212, 170, 0.08));\\n}\\n\\n/* ============================================\\n   CINEMA VISUAL LAYER - Film Studio Aesthetic\\n   ============================================ */\\n\\n/* 1. Film Grain Texture Overlay */\\n:root {\\n  --film-grain-opacity: 0.04;\\n}\\n\\n.film-grain-overlay::before {\\n  content: '';\\n  position: fixed;\\n  inset: 0;\\n  pointer-events: none;\\n  z-index: 0;\\n  opacity: var(--film-grain-opacity);\\n  background-image: url(\\\"data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E\\\");\\n  background-size: 400px;\\n  animation: grainShift 8s steps(10) infinite;\\n}\\n\\n@keyframes grainShift {\\n  0%, 100% { background-position: 0 0; }\\n  10% { background-position: 100px 0; }\\n  20% { background-position: 0 100px; }\\n  30% { background-position: 100px 100px; }\\n  40% { background-position: 200px 0; }\\n  50% { background-position: 0 200px; }\\n  60% { background-position: 200px 100px; }\\n  70% { background-position: 100px 200px; }\\n  80% { background-position: 200px 200px; }\\n  90% { background-position: 0 0; }\\n}\\n\\n/* Apply film grain to studio shell main area */\\n.studio-shell-main {\\n  position: relative;\\n}\\n\\n.studio-shell-main::before {\\n  content: '';\\n  position: absolute;\\n  inset: 0;\\n  pointer-events: none;\\n  z-index: 0;\\n  opacity: var(--film-grain-opacity);\\n  background-image: url(\\\"data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E\\\");\\n  background-size: 400px;\\n  animation: grainShift 8s steps(10) infinite;\\n}\\n\\n/* 2. Scene Thumbnail Film Frame Placeholders */\\n.aspect-widescreen {\\n  position: relative;\\n  aspect-ratio: 2.39 / 1;\\n  background: linear-gradient(135deg, #0d1526 0%, #111827 50%, #0a0f1c 100%);\\n  border: 2px solid rgba(6, 182, 212, 0.15);\\n  border-radius: 12px;\\n  overflow: hidden;\\n}\\n\\n.aspect-widescreen::before {\\n  content: '';\\n  position: absolute;\\n  inset: 0;\\n  border: 1px solid rgba(6, 182, 212, 0.2);\\n  border-radius: 11px;\\n  pointer-events: none;\\n}\\n\\n.aspect-widescreen::after {\\n  content: '';\\n  position: absolute;\\n  inset: 4px;\\n  border: 1px solid rgba(6, 182, 212, 0.3);\\n  border-radius: 9px;\\n  pointer-events: none;\\n}\\n\\n/* Film frame with clapperboard pattern */\\n.aspect-widescreen .film-placeholder {\\n  position: absolute;\\n  inset: 0;\\n  display: flex;\\n  flex-direction: column;\\n  align-items: center;\\n  justify-content: center;\\n  color: rgba(6, 182, 212, 0.6);\\n}\\n\\n.aspect-widescreen .film-placeholder svg {\\n  width: 60%;\\n  height: 60%;\\n  opacity: 0.3;\\n}\\n\\n/* Clapperboard SVG placeholder */\\n.aspect-widescreen .clapperboard-placeholder {\\n  width: 100%;\\n  height: 100%;\\n  display: flex;\\n  align-items: center;\\n  justify-content: center;\\n  background: linear-gradient(135deg, transparent 0%, rgba(6, 182, 212, 0.05) 50%, transparent 100%);\\n}\\n\\n.aspect-widescreen .clapperboard-placeholder::before,\\n.aspect-widescreen .clapperboard-placeholder::after {\\n  content: '';\\n  position: absolute;\\n  width: 80%;\\n  height: 2px;\\n  background: linear-gradient(90deg, transparent, rgba(6, 182, 212, 0.4), transparent);\\n}\\n\\n.aspect-widescreen .clapperboard-placeholder::before {\\n  top: 30%;\\n}\\n\\n.aspect-widescreen .clapperboard-placeholder::after {\\n  top: 50%;\\n}\\n\\n/* Film strip perforations pattern */\\n@keyframes filmScroll {\\n  0% { transform: translateY(0); }\\n  100% { transform: translateY(-100px); }\\n}\\n\\n.film-strip-decoration {\\n  position: fixed;\\n  top: 0;\\n  right: 0;\\n  width: 40px;\\n  height: 100vh;\\n  pointer-events: none;\\n  z-index: 1;\\n  overflow: hidden;\\n  opacity: 0.05;\\n}\\n\\n.film-strip-decoration .strip {\\n  position: absolute;\\n  top: 0;\\n  left: 0;\\n  width: 100%;\\n  height: 200%;\\n  background: \\n    repeating-linear-gradient(\\n      to bottom,\\n      rgba(6, 182, 212, 0.8) 0px,\\n      rgba(6, 182, 212, 0.8) 2px,\\n      transparent 2px,\\n      transparent 8px\\n    ),\\n    linear-gradient(90deg, transparent, rgba(6, 182, 212, 0.1), transparent);\\n  animation: filmScroll 40s linear infinite;\\n}\\n\\n.film-strip-decoration .perf {\\n  position: absolute;\\n  top: 0;\\n  left: 50%;\\n  width: 4px;\\n  height: 100%;\\n  background: repeating-linear-gradient(\\n    to bottom,\\n    rgba(6, 182, 212, 0.8) 0px,\\n    rgba(6, 182, 212, 0.8) 2px,\\n    transparent 2px,\\n    transparent 8px\\n  );\\n  transform: translateX(-50%);\\n}\\n\\n/* 3. Cinematic Hero - Studio Home */\\n.cinematic-hero {\\n  position: relative;\\n  min-height: 100vh;\\n  background: \\n    linear-gradient(180deg, #040810 0%, #030306 40%, #010104 100%),\\n    radial-gradient(ellipse 80% 50% at 50% -10%, rgba(214, 169, 92, 0.07) 0%, transparent 70%),\\n    /* Deep navy to black with subtle teal light leak */\\n    radial-gradient(ellipse 60% 40% at 15% 5%, rgba(6, 182, 212, 0.08) 0%, transparent 40%),\\n    /* Amber lens flare effect */\\n    radial-gradient(ellipse 50% 30% at 85% 15%, rgba(214, 169, 92, 0.06) 0%, transparent 35%),\\n    /* Subtle vignette */\\n    radial-gradient(ellipse 120% 120% at 50% 50%, rgba(0, 0, 0, 0.2) 0%, transparent 70%);\\n  isolation: isolate;\\n  overflow: hidden;\\n}\\n\\n.cinematic-hero::before {\\n  content: '';\\n  position: absolute;\\n  inset: 0;\\n  background: \\n    radial-gradient(ellipse at center, rgba(6, 182, 212, 0.03) 0%, transparent 50%),\\n    linear-gradient(45deg, transparent 49%, rgba(6, 182, 212, 0.02) 50%, transparent 51%);\\n  pointer-events: none;\\n}\\n\\n.cinematic-hero::after {\\n  content: '';\\n  position: absolute;\\n  inset: 0;\\n  opacity: var(--film-grain-opacity);\\n  background-image: url(\\\"data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)'/%3E%3C/svg%3E\\\");\\n  background-size: 400px;\\n  animation: grainShift 8s steps(10) infinite;\\n  pointer-events: none;\\n}\\n\\n/* 4. Aspect Ratio Frame UI for Scene Cards */\\n.scene-frame {\\n  position: relative;\\n  border: 2px solid rgba(6, 182, 212, 0.25);\\n  border-radius: 16px;\\n  overflow: hidden;\\n  background: linear-gradient(135deg, #0d1526 0%, #111827 100%);\\n}\\n\\n.scene-frame::before {\\n  content: '';\\n  position: absolute;\\n  inset: 0;\\n  border: 1px solid rgba(6, 182, 212, 0.1);\\n  border-radius: 15px;\\n  pointer-events: none;\\n}\\n\\n/* Film frame corner markers (viewfinder style) */\\n.scene-frame-corner-marker {\\n  position: absolute;\\n  width: 24px;\\n  height: 24px;\\n  border-style: solid;\\n  border-color: rgba(6, 182, 212, 0.4);\\n  pointer-events: none;\\n}\\n\\n.scene-frame-corner-marker.top-left {\\n  top: 8px;\\n  left: 8px;\\n  border-width: 2px 0 0 2px;\\n  border-radius: 4px 0 0 0;\\n}\\n\\n.scene-frame-corner-marker.top-right {\\n  top: 8px;\\n  right: 8px;\\n  border-width: 2px 2px 0 0;\\n  border-radius: 0 4px 0 0;\\n}\\n\\n.scene-frame-corner-marker.bottom-left {\\n  bottom: 8px;\\n  left: 8px;\\n  border-width: 0 0 2px 2px;\\n  border-radius: 0 0 0 4px;\\n}\\n\\n.scene-frame-corner-marker.bottom-right {\\n  bottom: 8px;\\n  right: 8px;\\n  border-width: 0 2px 2px 0;\\n  border-radius: 0 0 4px 0;\\n}\\n\\n/* 5. Animated Film Strip - Sidebar */\\n.sidebar-film-strip {\\n  position: fixed;\\n  top: 0;\\n  left: 0;\\n  width: 30px;\\n  height: 100vh;\\n  pointer-events: none;\\n  z-index: 1;\\n  overflow: hidden;\\n  opacity: 0.08;\\n}\\n\\n.sidebar-film-strip .film {\\n  position: absolute;\\n  top: 0;\\n  left: 0;\\n  width: 100%;\\n  height: 200%;\\n  background: \\n    repeating-linear-gradient(\\n      to bottom,\\n      transparent 0px,\\n      rgba(6, 182, 212, 0.8) 1px,\\n      rgba(6, 182, 212, 0.8) 2px,\\n      transparent 2px,\\n      transparent 16px\\n    ),\\n    repeating-linear-gradient(\\n      90deg,\\n      rgba(6, 182, 212, 0.1),\\n      rgba(6, 182, 212, 0.1) 2px,\\n      transparent 2px,\\n      transparent 8px\\n    );\\n  animation: filmScroll 60s linear infinite;\\n}\\n\\n/* 6. Room-specific Visual Identity Icons */\\n/* These are applied via className on navigation elements */\\n\\n/* Writers Room - Typewriter/Pen icon styling */\\n.room-icon-writers { background: linear-gradient(135deg, rgba(6, 182, 212, 0.15), transparent); }\\n.room-icon-writers::before { content: \\\"\ud83d\udd8b\ufe0f\\\"; font-size: 1.2em; }\\n\\n/* Previs Room - Storyboard frames */\\n.room-icon-previs { background: linear-gradient(135deg, rgba(214, 169, 92, 0.15), transparent); }\\n.room-icon-previs::before { content: \\\"\ud83c\udf9e\ufe0f\\\"; font-size: 1.2em; }\\n\\n/* Approval Room - Clapperboard */\\n.room-icon-approval { background: linear-gradient(135deg, rgba(16, 185, 129, 0.15), transparent); }\\n.room-icon-approval::before { content: \\\"\ud83c\udfac\\\"; font-size: 1.2em; }\\n\\n/* Study Room - Film reel */\\n.room-icon-study { background: linear-gradient(135deg, rgba(148, 163, 184, 0.15), transparent); }\\n.room-icon-study::before { content: \\\"\ud83c\udfa5\\\"; font-size: 1.2em; }\\n\\n/* Crew Ops - Director's chair */\\n.room-icon-crew { background: linear-gradient(135deg, rgba(245, 158, 11, 0.15), transparent); }\\n.room-icon-crew::before { content: \\\"\ud83e\ude91\\\"; font-size: 1.2em; }\\n\\n/* Cost Manager - Slate/budget board */\\n.room-icon-cost { background: linear-gradient(135deg, rgba(239, 68, 68, 0.15), transparent); }\\n.room-icon-cost::before { content: \\\"\ud83d\udcb0\\\"; font-size: 1.2em; }\\n\\n/* Workspace - Editing timeline */\\n.room-icon-workspace { background: linear-gradient(135deg, rgba(16, 185, 129, 0.15), transparent); }\\n.room-icon-workspace::before { content: \\\"\u2702\ufe0f\\\"; font-size: 1.2em; }\\n\\n/* Studio Home - Movie camera */\\n.room-icon-home { background: linear-gradient(135deg, rgba(214, 169, 92, 0.15), transparent); }\\n.room-icon-home::before { content: \\\"\ud83c\udfa5\\\"; font-size: 1.2em; }\\n\\n/* Enhanced clapperboard SVG for placeholders */\\n.clapperboard-svg {\\n  width: 100%;\\n  height: 100%;\\n  opacity: 0.5;\\n}\\n\\n.clapperboard-svg path {\\n  stroke: rgba(6, 182, 212, 0.6);\\n  stroke-width: 1.5;\\n  fill: none;\\n}\\n\\n.clapperboard-svg line {\\n  stroke: rgba(6, 182, 212, 0.4);\\n  stroke-width: 1;\\n}\\n\\n/* Light leak effect for special sections */\\n.light-leak {\\n  position: absolute;\\n  pointer-events: none;\\n  z-index: 0;\\n  border-radius: 50%;\\n  filter: blur(40px);\\n}\\n\\n.light-leak-teal {\\n  background: radial-gradient(circle, rgba(6, 182, 212, 0.15) 0%, transparent 70%);\\n}\\n\\n.light-leak-amber {\\n  background: radial-gradient(circle, rgba(214, 169, 92, 0.12) 0%, transparent 70%);\\n}\\n\\n/* Vignette effect for focused areas */\\n.vignette {\\n  position: relative;\\n}\\n\\n.vignette::before {\\n  content: '';\\n  position: absolute;\\n  inset: 0;\\n  border-radius: inherit;\\n  background: radial-gradient(ellipse at center, transparent 0%, rgba(0, 0, 0, 0.3) 100%);\\n  pointer-events: none;\\n  z-index: 1;\\n}\\n\\n/* Subtle lens flare effect */\\n.lens-flare {\\n  position: absolute;\\n  pointer-events: none;\\n  z-index: 0;\\n  border-radius: 50%;\\n  background: \\n    radial-gradient(circle, rgba(214, 169, 92, 0.1) 0%, transparent 30%),\\n    conic-gradient(from 0deg, transparent 0deg, rgba(214, 169, 92, 0.05) 10deg, transparent 20deg);\\n  filter: blur(20px);\\n}\\n\\n/* Film burn effect for edges */\\n.film-burn {\\n  position: absolute;\\n  pointer-events: none;\\n  z-index: 0;\\n  background: \\n    linear-gradient(\\n      to right,\\n      transparent 0%,\\n      rgba(0, 0, 0, 0.8) 50%,\\n      transparent 100%\\n    );\\n  opacity: 0.5;\\n}\\n\\n/* Animated subtle pulse for active elements */\\n@keyframes subtlePulse {\\n  0%, 100% { opacity: 0.03; }\\n  50% { opacity: 0.06; }\\n}\\n\\n.subtle-pulse {\\n  animation: subtlePulse 4s ease-in-out infinite;\\n}\\n\\n/* Responsive adjustments */\\n@media (max-width: 768px) {\\n  .film-strip-decoration {\\n    width: 20px;\\n    opacity: 0.03;\\n  }\\n  \\n  .aspect-widescreen {\\n    border-radius: 8px;\\n  }\\n  \\n  .scene-frame {\\n    border-radius: 12px;\\n  }\\n}\\n\\n@media (max-width: 480px) {\\n  .film-strip-decoration {\\n    display: none;\\n  }\\n}\\n\\n</content>\\n<metadata>\\nTotal lines: 1944, returned complete file\\n</metadata>\"}], \"action_name\": \"ToolReadFile\", \"message\": \"Action 'ToolReadFile' completed successfully\"}", "content_length": 50004, "message": "{\"success\": true, \"result\": [{\"type\": \"text\", \"text\": \"<filename>studio-app/src/index.css</filename>\\n<content>\\n@import \\\"tailwindcss\\\";\\n@import \\\"./styles/studio-pro-design-system.css\\\";\\n@import \\\"./styles/design-tokens.css\\\";\\n\\n/* Apply design system variables to base layer for Tailwind v4 */\\n@layer base {\\n  :root {\\n    /* Design system colors */\\n    --bg-void: #040810;\\n    --bg-primary: #080f1a;\\n    --bg-secondary: #0d1526;\\n    --bg-elevated: #111d2e;\\n    --bg-hover: #162236;\\n    --border-subtle: #1a2744;\\n    --border-default: #243452;\\n    --border-active: #2d4470;\\n    --text-primary: #e8edf5;\\n    --text-secondary: #8896b0;\\n    --text-dimmed: #4a5568;\\n    --text-mono: #5b8dd9;\\n    --accent-purple: #7c6af7;\\n    --accent-amber: #e8a020;\\n    --accent-green: #2ecc7a;\\n    --accent-red: #e05050;\\n    --accent-cyan: #38b2c8;\\n  }\\n\\n  body {\\n    background-color: #040810;\\n    color: #e8edf5;\\n    font-family: 'Inter', system-ui, sans-serif;\\n  }\\n\\n  /* Utility classes */\\n  .mono {\\n    font-family: 'JetBrains Mono', 'Fira Code', 'Consolas', monospace;\\n    color: #5b8dd9;\\n  }\\n\\n  /* Card/Panel components */\\n  .studio-card,\\n  .studio-panel {\\n    background: #0d1526;\\n    border: 1px solid #1a2744;\\n    border-radius: 8px;\\n    padding: 20px;\\n  }\\n\\n  /* Primary buttons */\\n  .btn-studio-primary {\\n    background: #7c6af7;\\n    color: #040810;\\n    border: none;\\n    border-radius: 5px;\\n    font-weight: 600;\\n    padding: 10px 20px;\\n    cursor: pointer;\\n    transition: opacity 150ms ease;\\n  }\\n\\n  .btn-studio-primary:hover {\\n    opacity: 0.9;\\n  }\\n\\n  /* Secondary buttons */\\n  .btn-studio-secondary {\\n    background: transparent;\\n    border: 1px solid #334155;\\n    color: #8896b0;\\n    border-radius: 5px;\\n    font-weight: 600;\\n    padding: 10px 20px;\\n    cursor: pointer;\\n    transition: all 150ms ease;\\n  }\\n\\n  .btn-studio-secondary:hover {\\n    border-color: #475569;\\n    color: #e8edf5;\\n  }\\n\\n  /* Navigation */\\n  .studio-nav {\\n    background: #080f1a;\\n    border-bottom: 1px solid #1a2744;\\n  }\\n\\n  .studio-nav-tab {\\n    color: #4a5568;\\n    background: transparent;\\n    border: none;\\n    padding: 12px 20px;\\n    cursor: pointer;\\n    transition: color 150ms ease;\\n    border-bottom: 2px solid transparent;\\n  }\\n\\n  .studio-nav-tab:hover {\\n    color: #8896b0;\\n  }\\n\\n  .studio-nav-tab-active {\\n    color: #e8edf5;\\n    border-bottom-color: #7c6af7;\\n  }\\n\\n  /* Advisory panel (replaces red blocked banner) */\\n  .studio-advisory {\\n    border-left: 3px solid #e8a020;\\n    background: #0d1526;\\n    border-top: 1px solid #1a2744;\\n    border-right: 1px solid #1a2744;\\n    border-bottom: 1px solid #1a2744;\\n    border-radius: 8px;\\n    padding: 20px;\\n  }\\n}\\n\\n/* Legacy variables - will be gradually migrated to design system */\\n:root {\\n  --font-display: 'Inter', system-ui, -apple-system, sans-serif;\\n  --font-body: 'Inter', system-ui, -apple-system, sans-serif;\\n  --brand-cyan-100: #d5f6f3;\\n  --brand-cyan-300: #7ad6d1;\\n  --brand-amber-200: #efcc93;\\n  --brand-amber-400: #d6a95c;\\n  --brand-rose-300: #d08383;\\n  --cinematic-gradient-panel: linear-gradient(180deg, rgba(255, 255, 255, 0.05), rgba(255, 255, 255, 0.02));\\n  --cinematic-gradient-chip: linear-gradient(140deg, rgba(214, 169, 92, 0.18), rgba(122, 214, 209, 0.1));\\n  --studio-glow-soft: 0 0 22px rgba(122, 214, 209, 0.16);\\n  --studio-glow-strong: 0 0 28px rgba(214, 169, 92, 0.22);\\n  --studio-shadow-cinematic: 0 24px 60px rgba(0, 0, 0, 0.45);\\n  --studio-shadow-elevated: 0 16px 34px rgba(0, 0, 0, 0.34);\\n  --studio-panel-space: 12px;\\n  --studio-panel-space-sm: 8px;\\n  --studio-panel-space-lg: 16px;\\n  --studio-blur-sm: blur(8px);\\n  --studio-blur-md: blur(12px);\\n  --studio-blur-lg: blur(16px);\\n  --studio-border-glow: rgba(255, 255, 255, 0.16);\\n  --studio-border-glow-strong: rgba(122, 214, 209, 0.44);\\n  --state-idle-a: rgba(122, 214, 209, 0.08);\\n  --state-generating-a: rgba(125, 211, 252, 0.14);\\n  --state-reviewing-a: rgba(214, 169, 92, 0.12);\\n  --state-failed-a: rgba(96, 120, 170, 0.14);\\n  --state-completed-a: rgba(214, 169, 92, 0.2);\\n  --bg-deep: #050505;\\n  --bg-panel: rgba(16, 16, 18, 0.62);\\n  --bg-card: rgba(21, 21, 24, 0.72);\\n  --bg-card-hover: rgba(30, 30, 34, 0.82);\\n  --border: rgba(255, 255, 255, 0.1);\\n  --border-accent: rgba(214, 169, 92, 0.35);\\n  --text-primary: #f2eee9;\\n  --text-secondary: #b8b1a7;\\n  --text-muted: #8d867b;\\n  --accent-cyan: #7ad6d1;\\n  --accent-purple: #9f8dc5;\\n  --accent-green: #78b38a;\\n  --accent-orange: #b88762;\\n  --accent-amber: #d6a95c;\\n  --accent-red-soft: #d08383;\\n  --panel-shadow: 0 20px 44px rgba(0, 0, 0, 0.42);\\n  --studio-space-xs: 6px;\\n  --studio-space-sm: 10px;\\n  --studio-space-md: 14px;\\n  --studio-space-lg: 20px;\\n  --studio-space-xl: 28px;\\n}\\n\\n* {\\n  box-sizing: border-box;\\n}\\n\\nhtml, body, #root {\\n  height: 100%;\\n  margin: 0;\\n  padding: 0;\\n}\\n\\nhtml {\\n  scroll-behavior: smooth;\\n}\\n\\nbody {\\n  background: var(--bg-void);\\n  color: var(--text-primary);\\n  font-family: 'Inter', system-ui, sans-serif;\\n  font-size: 13px;\\n  line-height: 1.6;\\n  -webkit-font-smoothing: antialiased;\\n  -moz-osx-font-smoothing: grayscale;\\n  overflow-x: hidden;\\n  letter-spacing: 0.01em;\\n  position: relative;\\n  margin: 0;\\n  padding: 0;\\n}\\n\\n#root {\\n  display: flex;\\n  flex-direction: column;\\n  min-height: 100vh;\\n  width: 100%;\\n}\\n\\n::-webkit-scrollbar {\\n  width: 8px;\\n  height: 8px;\\n}\\n::-webkit-scrollbar-track {\\n  background: var(--bg-primary);\\n}\\n::-webkit-scrollbar-thumb {\\n  background: var(--border-default);\\n  border-radius: 4px;\\n}\\n::-webkit-scrollbar-thumb:hover {\\n  background: var(--text-dimmed);\\n}\\n\\ninput, textarea, select {\\n  font-family: inherit;\\n}\\n\\n.glass-panel {\\n  background: var(--bg-panel);\\n  backdrop-filter: blur(18px);\\n  border: 1px solid var(--border);\\n  border-radius: 16px;\\n  box-shadow: var(--panel-shadow);\\n}\\n\\n.glass-card {\\n  background: var(--bg-card);\\n  backdrop-filter: blur(12px);\\n  border: 1px solid var(--border);\\n  border-radius: 16px;\\n  box-shadow: 0 10px 28px rgba(0, 0, 0, 0.28);\\n}\\n\\n.cinematic-panel {\\n  border-radius: 1rem;\\n  border: 1px solid var(--studio-border-glow);\\n  background: var(--cinematic-gradient-panel);\\n  backdrop-filter: var(--studio-blur-md);\\n  box-shadow: var(--studio-shadow-elevated), var(--studio-glow-soft);\\n  padding: var(--studio-panel-space);\\n}\\n\\n.studio-status-chip {\\n  border-radius: 999px;\\n  border: 1px solid var(--studio-border-glow);\\n  background: var(--cinematic-gradient-chip);\\n  padding: 2px 8px;\\n  font-size: 10px;\\n  text-transform: uppercase;\\n  letter-spacing: 0.1em;\\n}\\n\\n.studio-icon-chip {\\n  border-radius: 10px;\\n  border: 1px solid var(--studio-border-glow);\\n  background: rgba(0, 0, 0, 0.28);\\n  backdrop-filter: var(--studio-blur-sm);\\n  box-shadow: var(--studio-glow-soft);\\n}\\n\\n.studio-nav-link {\\n  border-radius: 8px;\\n  transition: all 180ms ease;\\n}\\n\\n.studio-nav-link:hover {\\n  box-shadow: var(--studio-glow-soft);\\n}\\n\\n.accent-glow {\\n  box-shadow: 0 0 20px rgba(0, 200, 255, 0.15);\\n}\\n\\n.neon-border {\\n  border-color: var(--accent-cyan);\\n  box-shadow: 0 0 8px rgba(0, 200, 255, 0.3), inset 0 0 8px rgba(0, 200, 255, 0.05);\\n}\\n\\n.status-dot {\\n  width: 8px;\\n  height: 8px;\\n  border-radius: 50%;\\n}\\n\\n.status-active {\\n  background: var(--accent-green);\\n  box-shadow: 0 0 6px var(--accent-green);\\n}\\n\\n.