(0, 212, 170, 0.06), transparent 70%),\\n    url('https://images.unsplash.com/photo-1489599849927-2ee91cede3ba?auto=format&fit=crop&w=2400&q=80') center/cover no-repeat;\\n  filter: saturate(0.8) contrast(1.06) brightness(0.52);\\n  transform: scale(1.03);\\n}\\n\\n.studio-room-shell {\\n  position: relative;\\n  isolation: isolate;\\n}\\n\\n.studio-room-shell::before {\\n  content: '';\\n  position: fixed;\\n  inset: 0;\\n  pointer-events: none;\\n  background:\\n    radial-gradient(900px 420px at 50% -6%, rgba(214, 169, 92, 0.08), transparent 70%),\\n    radial-gradient(840px 420px at 88% 8%, rgba(122, 214, 209, 0.08), transparent 72%);\\n  z-index: -3;\\n  animation: ambient-shift 36s ease-in-out infinite alternate;\\n}\\n\\n.studio-room-shell::after {\\n  content: '';\\n  position: fixed;\\n  inset: 0;\\n  pointer-events: none;\\n  background:\\n    radial-gradient(circle at center, transparent 56%, rgba(0, 0, 0, 0.46) 100%),\\n    repeating-linear-gradient(0deg, rgba(255,255,255,0.008), rgba(255,255,255,0.008) 1px, transparent 2px, transparent 4px);\\n  mix-blend-mode: soft-light;\\n  opacity: 0.45;\\n  z-index: -2;\\n}\\n\\n.shell-overview::before {\\n  background:\\n    radial-gradient(700px 360px at 24% 8%, rgba(122, 214, 209, 0.12), transparent 72%),\\n    radial-gradient(840px 420px at 76% 12%, rgba(214, 169, 92, 0.1), transparent 74%);\\n}\\n\\n.shell-writers::before {\\n  background:\\n    radial-gradient(700px 380px at 18% 10%, rgba(214, 169, 92, 0.12), transparent 72%),\\n    radial-gradient(820px 420px at 76% 16%, rgba(159, 141, 197, 0.09), transparent 74%);\\n}\\n\\n.shell-previs::before {\\n  background:\\n    radial-gradient(720px 400px at 14% 10%, rgba(122, 214, 209, 0.12), transparent 72%),\\n    repeating-linear-gradient(90deg, rgba(255,255,255,0.018), rgba(255,255,255,0.018) 3px, transparent 5px, transparent 20px);\\n}\\n\\n.shell-production::before {\\n  background:\\n    radial-gradient(720px 400px at 80% 10%, rgba(184, 135, 98, 0.12), transparent 72%),\\n    linear-gradient(120deg, rgba(255,255,255,0.02), transparent 45%);\\n}\\n\\n.shell-screening::before {\\n  background:\\n    radial-gradient(860px 420px at 50% -4%, rgba(122, 214, 209, 0.1), transparent 70%),\\n    linear-gradient(180deg, rgba(0,0,0,0.12), transparent 30%);\\n}\\n\\n.shell-archive::before {\\n  background:\\n    radial-gradient(700px 380px at 20% 8%, rgba(159, 141, 197, 0.1), transparent 72%),\\n    radial-gradient(760px 360px at 80% 14%, rgba(214, 169, 92, 0.1), transparent 72%);\\n}\\n\\n.shell-study::before {\\n  background:\\n    radial-gradient(760px 400px at 18% 8%, rgba(122, 214, 209, 0.1), transparent 72%),\\n    radial-gradient(760px 420px at 82% 16%, rgba(214, 169, 92, 0.08), transparent 74%);\\n}\\n\\n.cinematic-panel {\\n  transition: opacity 220ms ease, transform 220ms ease, border-color 220ms ease, box-shadow 220ms ease;\\n  animation: panel-fade-in 220ms ease both;\\n}\\n\\n.cinematic-panel:hover {\\n  transform: translateY(-2px);\\n  border-color: rgba(214, 169, 92, 0.35);\\n  box-shadow: 0 18px 38px rgba(0, 0, 0, 0.42), 0 0 0 1px rgba(214, 169, 92, 0.08) inset;\\n}\\n\\n.room-hero-frame {\\n  position: relative;\\n  overflow: hidden;\\n}\\n\\n.room-hero-frame::after {\\n  content: '';\\n  position: absolute;\\n  inset: -1px;\\n  pointer-events: none;\\n  border: 1px solid rgba(122, 214, 209, 0.34);\\n  box-shadow: 0 0 26px rgba(122, 214, 209, 0.14);\\n  border-radius: inherit;\\n}\\n\\n.tab-active-glow {\\n  position: relative;\\n}\\n\\n.tab-active-glow::after {\\n  content: '';\\n  position: absolute;\\n  left: 10%;\\n  right: 10%;\\n  bottom: -2px;\\n  height: 1px;\\n  background: linear-gradient(90deg, transparent, rgba(214, 169, 92, 0.92), transparent);\\n  animation: tab-slide 180ms ease both;\\n}\\n\\n.status-pulse-soft {\\n  animation: status-pulse 2.6s ease-in-out infinite;\\n}\\n\\n.playback-glow {\\n  animation: playback-pulse 1.8s ease-in-out infinite;\\n}\\n\\n.dropzone-glow {\\n  box-shadow: 0 0 0 1px rgba(214, 169, 92, 0.45), 0 0 26px rgba(214, 169, 92, 0.2);\\n}\\n\\n.skeleton-shimmer {\\n  position: relative;\\n  overflow: hidden;\\n  background: rgba(255, 255, 255, 0.06);\\n}\\n\\n.skeleton-shimmer::after {\\n  content: '';\\n  position: absolute;\\n  inset: 0;\\n  transform: translateX(-100%);\\n  background: linear-gradient(90deg, transparent, rgba(255,255,255,0.12), transparent);\\n  animation: shimmer 1.6s ease-in-out infinite;\\n}\\n\\n@keyframes ambient-shift {\\n  from { transform: translate3d(-1%, 0, 0) scale(1); }\\n  to { transform: translate3d(1%, 0.5%, 0) scale(1.03); }\\n}\\n\\n@keyframes panel-fade-in {\\n  from { opacity: 0; transform: translateY(5px); }\\n  to { opacity: 1; transform: translateY(0); }\\n}\\n\\n@keyframes tab-slide {\\n  from { opacity: 0; transform: scaleX(0.4); }\\n  to { opacity: 1; transform: scaleX(1); }\\n}\\n\\n@keyframes shimmer {\\n  100% { transform: translateX(100%); }\\n}\\n\\n@keyframes status-pulse {\\n  0%, 100% { box-shadow: 0 0 0 rgba(245, 158, 11, 0); }\\n  50% { box-shadow: 0 0 16px rgba(245, 158, 11, 0.26); }\\n}\\n\\n@keyframes playback-pulse {\\n  0%, 100% { box-shadow: 0 0 0 rgba(122, 214, 209, 0.12); }\\n  50% { box-shadow: 0 0 22px rgba(122, 214, 209, 0.32); }\\n}\\n\\n@media (prefers-reduced-motion: reduce) {\\n  .studio-room-shell::before,\\n  .cinematic-panel,\\n  .status-pulse-soft,\\n  .playback-glow,\\n  .skeleton-shimmer::after,\\n  .tab-active-glow::after {\\n    animation: none !important;\\n    transition: none !important;\\n  }\\n}\\n\\n.studio-landing-grain {\\n  position: absolute;\\n  inset: 0;\\n  pointer-events: none;\\n  opacity: 0.16;\\n  background-image: radial-gradient(rgba(255, 255, 255, 0.25) 0.4px, transparent 0.4px);\\n  background-size: 3px 3px;\\n  mix-blend-mode: soft-light;\\n}\\n\\n.studio-landing-vignette {\\n  position: absolute;\\n  inset: 0;\\n  pointer-events: none;\\n  background:\\n    radial-gradient(120% 120% at 50% 50%, transparent 44%, rgba(0, 0, 0, 0.72) 100%),\\